/*Table structure for table `config_prioridades` */

DROP TABLE IF EXISTS `config_prioridades`;

CREATE TABLE `config_prioridades` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nom_priori` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nivel` int NOT NULL DEFAULT '0',
  `tiempo` int NOT NULL DEFAULT '0',
  `tipo_tiempo` enum('Dias','Horas','Minutos','No Aplica') COLLATE utf8mb4_unicode_ci NOT NULL,
  `observacion` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `config_prioridades` */

insert  into `config_prioridades`(`id`,`nom_priori`,`nivel`,`tiempo`,`tipo_tiempo`,`observacion`,`estado`,`created_at`,`updated_at`) values (1,'Alta',1,4,'Horas',NULL,1,'2024-05-16 22:44:18','2024-05-16 22:44:18'),(2,'Media',2,24,'Horas',NULL,1,'2024-05-16 22:44:18','2024-05-16 22:44:18'),(3,'Baja',3,3,'Dias','Habiles',1,'2024-05-16 22:44:18','2024-05-16 22:44:18'),(4,'Sin Prioridad',4,3,'Dias','Habiles',1,'2024-05-16 22:44:18','2024-05-16 22:44:18');

/*Table structure for table `config_productos` */

DROP TABLE IF EXISTS `config_productos`;

CREATE TABLE `config_productos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `cod_cups` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nom_produc` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `porcen` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '0',
  `val_produc` double(8,2) DEFAULT '0.00',
  `requi_lectura` tinyint(1) DEFAULT '1',
  `tipo_oral` tinyint(1) DEFAULT '0',
  `tipo_venoso` tinyint(1) DEFAULT '0',
  `factura` tinyint(1) DEFAULT '0',
  `estado` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

