/*Table structure for table `estudios` */

DROP TABLE IF EXISTS `estudios`;

CREATE TABLE `estudios` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `study_pk` bigint NOT NULL,
  `study_iuid` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `study_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fec_estudio` datetime NOT NULL,
  `accession_no` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `study_desc` varchar(250) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mods_in_study` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_reportar` varchar(70) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paciente_id` bigint unsigned NOT NULL,
  `medico_id` bigint unsigned NOT NULL,
  `quien_registro_id` bigint unsigned NOT NULL,
  `sede_id` bigint unsigned NOT NULL,
  `prioridad_id` bigint unsigned NOT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `atencion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `servicio` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `eps` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contrato` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plan` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `estudios_paciente_id_foreign` (`paciente_id`),
  KEY `estudios_medico_id_foreign` (`medico_id`),
  KEY `estudios_quien_registro_id_foreign` (`quien_registro_id`),
  KEY `estudios_sede_id_foreign` (`sede_id`),
  KEY `estudios_prioridad_id_foreign` (`prioridad_id`),
  CONSTRAINT `estudios_medico_id_foreign` FOREIGN KEY (`medico_id`) REFERENCES `users` (`id`),
  CONSTRAINT `estudios_paciente_id_foreign` FOREIGN KEY (`paciente_id`) REFERENCES `pacientes` (`id`),
  CONSTRAINT `estudios_prioridad_id_foreign` FOREIGN KEY (`prioridad_id`) REFERENCES `config_prioridades` (`id`),
  CONSTRAINT `estudios_quien_registro_id_foreign` FOREIGN KEY (`quien_registro_id`) REFERENCES `users` (`id`),
  CONSTRAINT `estudios_sede_id_foreign` FOREIGN KEY (`sede_id`) REFERENCES `config_sedes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2886 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `estudios` */

