/*Table structure for table `estudios_audios` */

DROP TABLE IF EXISTS `estudios_audios`;

CREATE TABLE `estudios_audios` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `estudio_id` bigint unsigned NOT NULL,
  `estudio_producto_id` bigint unsigned NOT NULL,
  `audio` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `estudios_audios_estudio_id_foreign` (`estudio_id`),
  KEY `estudios_audios_estudio_producto_id_foreign` (`estudio_producto_id`),
  CONSTRAINT `estudios_audios_estudio_id_foreign` FOREIGN KEY (`estudio_id`) REFERENCES `estudios` (`id`),
  CONSTRAINT `estudios_audios_estudio_producto_id_foreign` FOREIGN KEY (`estudio_producto_id`) REFERENCES `estudios_productos` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `estudios_audios` */

/*Table structure for table `estudios_diagnosticos` */

DROP TABLE IF EXISTS `estudios_diagnosticos`;

CREATE TABLE `estudios_diagnosticos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `estudio_id` bigint unsigned DEFAULT NULL,
  `cod_diagnos` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nom_diagnos` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `estudios_diagnosticos_estudio_id_foreign` (`estudio_id`),
  CONSTRAINT `estudios_diagnosticos_estudio_id_foreign` FOREIGN KEY (`estudio_id`) REFERENCES `estudios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

