/*Table structure for table `estudios_productos` */

DROP TABLE IF EXISTS `estudios_productos`;

CREATE TABLE `estudios_productos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `estudio_id` bigint unsigned NOT NULL,
  `producto_id` bigint unsigned NOT NULL,
  `transcriptor_id` bigint unsigned DEFAULT NULL,
  `cod_cups` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nom_produc` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fechor_lectura` datetime DEFAULT NULL,
  `lectura` text COLLATE utf8mb4_unicode_ci,
  `fechor_trascrito` datetime DEFAULT NULL,
  `medico_ordena` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `estudios_productos_estudio_id_foreign` (`estudio_id`),
  KEY `estudios_productos_producto_id_foreign` (`producto_id`),
  KEY `estudios_productos_transcriptor_id_foreign` (`transcriptor_id`),
  CONSTRAINT `estudios_productos_estudio_id_foreign` FOREIGN KEY (`estudio_id`) REFERENCES `estudios` (`id`),
  CONSTRAINT `estudios_productos_producto_id_foreign` FOREIGN KEY (`producto_id`) REFERENCES `config_productos` (`id`),
  CONSTRAINT `estudios_productos_transcriptor_id_foreign` FOREIGN KEY (`transcriptor_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3725 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `estudios_productos` */

insert  into `estudios_productos`(`id`,`estudio_id`,`producto_id`,`transcriptor_id`,`cod_cups`,`nom_produc`,`fechor_lectura`,`lectura`,`fechor_trascrito`,`medico_ordena`,`visible`,`activo`,`created_at`,`updated_at`) values (1,1,81,6,'879460','TOMOGRAFIA AXIAL COMPUTADA DE PELVIS','2024-04-20 07:38:15','Atenció: 5955671\r\nFecha y Hora: 2024-04-20 07:37:37\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE PELVIS\r\n\r\nTÉCNICA\r\nCon tomógrafo multidetector empleando técnica helicoidal se realizan cortes finos de pelvis, posteriormente se realiza algoritmo de ventana ósea y se realizan reconstrucciones multiplanares.\r\nHALLAZGOS\r\nFractura conminuta el cuello del fémur derecho.\r\nNo se observan otras lesiones óseas focales o trazos de fractura.\r\nLa relación cortico medular es normal.\r\nLos espacios articulares visualizados se hallan conservados.\r\nLos tendones y ligamentos valorados por este método no presentan signos de lesión.\r\nLos órganos pélvicos visualizados impresionan sin alteraciones\r\nLos tejidos blandos y grupos musculares visualizados por este método son de apariencia normal.\r\nCONCLUSIÓN\r\nFractura conminuta el cuello del fémur derecho.\r\nEl resto del estudio impresiona dentro parámetros normales para la edad del paciente','2024-04-20 07:38:34',NULL,1,1,'2024-05-16 22:44:37','2024-05-16 22:44:37'),(2,2,123,9,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-21 16:58:29','Atenció: 5956117\r\nFecha y Hora: 2024-04-20 09:44:09\r\n\r\nRADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL\r\n\r\n\r\nOpacidad que compromete los ⅔ inferiores del hemitórax derecho condicionando obliteración del contorno diafragmático y la silueta cardiaca por presencia de derrame pleural. \r\nLa transparencia y vascularización del pulmón izquierdo son satisfactorias.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n\r\nCONCLUSIÓN: DERRAME PLEURAL EN EL HEMITÓRAX DERECHO.  \r\n\r\n','2024-04-22 11:53:31',NULL,1,1,'2024-05-16 22:44:37','2024-05-16 22:44:37'),(3,3,50,9,'873333','RADIOGRAFIA DE PIE AP Y LATERAL','2024-04-21 17:00:40','Atenció: 5956184\r\nFecha y Hora: 2024-04-20 09:44:45\r\n\r\n\r\n\r\nRADIOGRAFÍA DE PIES COMPARATIVOS \r\n\r\nNo se observan alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\nNo hay particularidad en los tejidos blandos. \r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE PIES COMPARATIVOS DENTRO DE LÍMITES NORMALES.\r\n','2024-04-22 11:53:12',NULL,1,1,'2024-05-16 22:44:37','2024-05-16 22:44:37'),(4,3,58,9,'873431','RADIOGRAFIA DE TOBILLO AP LATERAL Y ROTACION INTERNA','2024-04-21 17:00:48','Atenció: 5956184\r\nFecha y Hora: 2024-04-20 09:44:45\r\n\r\nRADIOGRAFIA DE TOBILLO AP LATERAL Y ROTACION INTERNA\r\n COMPARATIVO \r\n\r\nNo se observan alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\nAumento en el espesor y la densidad de los tejidos blandos en la región maleolar derecha por edema. \r\n\r\nCONCLUSIÓN: EDEMA DE TEJIDOS EN EL CUELLO DE PIE DERECHO. \r\n\r\n','2024-04-22 11:53:23',NULL,1,1,'2024-05-16 22:44:37','2024-05-16 22:44:37'),(5,4,33,9,'872002','RADIOGRAFIA DE ABDOMEN SIMPLE','2024-04-21 17:01:18','Atenció: 5956211\r\nFecha y Hora: 2024-04-20 09:44:58\r\n\r\nRADIOGRAFIA DE ABDOMEN SIMPLE\r\n\r\nPACIENTE: LOPEZ GUERRA MÁXIMO \r\n\r\nRADIOGRAFÍA DE ABDOMEN \r\n\r\nLa distribución del patrón gaseoso intestinal es satisfactoria.\r\nLas siluetas renales y sombras de los músculos psoas tienen aspecto radiológico normal.\r\nNo hay signos radiológicos de obstrucción intestinal. \r\nNo se visualizan cálculos radiopacos.\r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE ABDOMEN DENTRO DE LÍMITES NORMALES.\r\n\r\n','2024-04-22 11:52:29',NULL,1,1,'2024-05-16 22:44:37','2024-05-16 22:44:37'),(6,5,123,9,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-21 17:02:08','Atenció: 5956205\r\nFecha y Hora: 2024-04-20 09:45:15\r\n\r\nRADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL\r\n\r\n\r\n\r\nProyección única AP. \r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón aumentado de tamaño. \r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n\r\n\r\n','2024-04-22 11:52:21',NULL,1,1,'2024-05-16 22:44:37','2024-05-16 22:44:37'),(7,6,44,9,'873210','RADIOGRAFIA DE MANO Y O DEDOS DE MANO','2024-04-21 18:27:04','Atenció: 5954983\r\nFecha y Hora: 2024-04-20 09:52:04\r\n\r\n\r\n\r\nRADIOGRAFÍA DE MANO IZQUIERDA \r\n\r\nEstudio técnicamente limitado por haber sido realizado a través de férula para inmovilización. \r\nFractura lineal incompleta en la metáfisis distal del radio sin desplazamiento de sus fragmentos principales. \r\nMaterial quirúrgico en el tercio distal del cúbito.  \r\nTejidos blandos no valorables.\r\nNo se observan otras alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\n\r\n','2024-04-22 11:52:10',NULL,1,1,'2024-05-16 22:44:38','2024-05-16 22:44:38'),(8,7,33,9,'872002','RADIOGRAFIA DE ABDOMEN SIMPLE','2024-04-21 18:27:37','Atenció: 5956247\r\nFecha y Hora: 2024-04-20 09:52:56\r\n\r\n\r\nRADIOGRAFÍA DE ABDOMEN \r\n\r\nLa distribución del patrón gaseoso intestinal es satisfactoria.\r\nLas siluetas renales y sombras de los músculos psoas tienen aspecto radiológico normal.\r\nNo hay signos radiológicos de obstrucción intestinal. \r\nNo se visualizan cálculos radiopacos.\r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE ABDOMEN DENTRO DE LÍMITES NORMALES.\r\n\r\n\r\n','2024-04-22 11:51:31',NULL,1,1,'2024-05-16 22:44:38','2024-05-16 22:44:38'),(9,8,123,9,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-21 18:28:40','Atenció: 5955895\r\nFecha y Hora: 2024-04-20 09:54:19\r\n\r\nRADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL\r\n\r\n\r\n\r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE TÓRAX DENTRO DE LÍMITES NORMALES.\r\n\r\n','2024-04-22 11:50:46',NULL,1,1,'2024-05-16 22:44:38','2024-05-16 22:44:38'),(10,9,58,9,'873431','RADIOGRAFIA DE TOBILLO AP LATERAL Y ROTACION INTERNA','2024-04-21 18:30:32','Atenció: 5956164\r\nFecha y Hora: 2024-04-20 09:54:48\r\n\r\nRADIOGRAFIA DE TOBILLO AP LATERAL Y ROTACION INTERNA\r\nDERECHO \r\n\r\nFractura oblicua completa en la metáfisis distal del peroné con ligero desplazamiento de sus fragmentos principales en sentido lateral. \r\nNo se observan otras alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\nAumento en el espesor y la densidad de los tejidos blandos en región maleolar por edema. \r\n\r\nCONCLUSIÓN: FRACTURA DEL TERCIO DISTAL DEL PERONÉ ASOCIADA A EDEMA DE TEJIDOS BLANDOS. \r\n','2024-04-22 11:50:40',NULL,1,1,'2024-05-16 22:44:38','2024-05-16 22:44:38'),(11,10,123,9,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-21 18:30:57','Atenció: 5956193\r\nFecha y Hora: 2024-04-20 09:55:45\r\n\r\nRADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL\r\n\r\n\r\n\r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE TÓRAX DENTRO DE LÍMITES NORMALES.','2024-04-22 11:50:33',NULL,1,1,'2024-05-16 22:44:38','2024-05-16 22:44:38'),(12,11,123,9,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-21 18:31:32','Atenció: 5956177\r\nFecha y Hora: 2024-04-20 09:56:09\r\n\r\nRADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL\r\n\r\n\r\n\r\nProyección única AP. \r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n\r\n\r\n','2024-04-22 11:50:27',NULL,1,1,'2024-05-16 22:44:38','2024-05-16 22:44:38'),(13,12,33,9,'872002','RADIOGRAFIA DE ABDOMEN SIMPLE','2024-04-21 18:32:25','Atenció: 5956166\r\nFecha y Hora: 2024-04-20 09:57:08\r\n\r\n\r\n\r\nRADIOGRAFÍA DE ABDOMEN \r\n\r\nClips metálicos proyectados sobre el hipocondrio derecho. \r\nLa distribución del patrón gaseoso intestinal es satisfactoria.\r\nLas siluetas renales y sombras de los músculos psoas tienen aspecto radiológico normal.\r\nNo hay signos radiológicos de obstrucción intestinal. \r\nNo se visualizan cálculos radiopacos.\r\n\r\n','2024-04-22 11:50:22',NULL,1,1,'2024-05-16 22:44:39','2024-05-16 22:44:39'),(14,13,58,9,'873431','RADIOGRAFIA DE TOBILLO AP LATERAL Y ROTACION INTERNA','2024-04-21 18:35:38','Atenció: 5948269\r\nFecha y Hora: 2024-04-20 09:57:37\r\n\r\nRADIOGRAFIA DE TOBILLO AP LATERAL Y ROTACION INTERNA\r\n IZQUIERDO \r\n\r\nEstudio técnicamente limitado por haber sido realizado a través de férula para inmovilización. \r\nFractura conminuta del tercio distal de la tibia que compromete la diáfisis cuyos fragmentos son mantenidos en posición a través de material quirúrgico. \r\nFractura oblicua en el tercio distal del peroné en localización diafisiaria cuyos fragmentos principales son mantenidos en posición a través de material quirúrgico. \r\nTejidos blandos no valorables.\r\nNo se observan otras alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\n\r\n','2024-04-22 11:50:15',NULL,1,1,'2024-05-16 22:44:39','2024-05-16 22:44:39'),(15,14,41,9,'873204','RADIOGRAFIA DE HOMBRO','2024-04-21 18:47:32','Atenció: 5956160\r\nFecha y Hora: 2024-04-20 09:58:18\r\n\r\n\r\nRADIOGRAFÍA DE HOMBRO DERECHO \r\n\r\nProyección única AP. \r\nFractura oblicua completa en el tercio medio de la diáfisis clavicular con desplazamiento de sus fragmentos principales. \r\nHipertrofia de la articulación acromio clavicular secundaria a cambios de tipo degenerativo. \r\nOsteofitos en la cabeza humeral y en el acromion. \r\nNo se observan otras alteraciones en las estructuras óseas visualizadas.\r\nLas demás relaciones articulares se encuentran conservadas. \r\nNo hay particularidad en los tejidos blandos. \r\n\r\n','2024-04-22 11:50:03',NULL,1,1,'2024-05-16 22:44:39','2024-05-16 22:44:39'),(16,14,123,9,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-21 18:47:41','Atenció: 5956160\r\nFecha y Hora: 2024-04-20 09:58:18\r\n\r\nRADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL\r\n\r\n\r\n\r\nProyección única AP. \r\nCorazón aumentado de tamaño;calcificaciones ateromatosas del cayado aórtico. \r\nOpacidades lineales no septales parenquimatosas pulmonares basales bilaterales correspondientes a atelectasias planas. \r\nLa transparencia y vascularización del resto de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\n','2024-04-22 11:50:08',NULL,1,1,'2024-05-16 22:44:39','2024-05-16 22:44:39'),(17,15,33,9,'872002','RADIOGRAFIA DE ABDOMEN SIMPLE','2024-04-21 18:41:43','Atenció: 5956257\r\nFecha y Hora: 2024-04-20 09:58:38\r\nIA \r\n\r\nRADIOGRAFÍA DE ABDOMEN \r\n\r\nProyección única AP debido a presencia de artificios condicionados por movimientos respiratorios del paciente por lo cual debe ser repetida para su adecuada interpretación. \r\n\r\n','2024-04-22 11:49:48',NULL,1,1,'2024-05-16 22:44:39','2024-05-16 22:44:39'),(18,15,124,NULL,'','PORTATILES SIN fluoroscopia  e intensificador de imAgenes practicado en habitacion  UCI RN o quirofanos al valor del estudio agregar',NULL,NULL,NULL,NULL,1,1,'2024-05-16 22:44:39','2024-05-16 22:44:39'),(19,16,123,9,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-21 18:47:51','Atenció: 5956160\r\nFecha y Hora: 2024-04-20 09:59:00\r\n\r\nRADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL\r\n\r\n\r\n\r\nCorazón aumentado de tamaño;calcificaciones ateromatosas del cayado aórtico.\r\nOpacidades lineales no septales parenquimatosas pulmonares basales bilaterales correspondientes a bandas atelectásicas planas. \r\nLa transparencia y vascularización del resto de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nCambios degenerativos de la columna dorsal. \r\n\r\nCONCLUSIÓN: CARDIOMEGALIA. ATELECTASIAS PLANAS PULMONARES BIBASALES. ','2024-04-22 11:49:28',NULL,1,1,'2024-05-16 22:44:39','2024-05-16 22:44:39'),(20,16,41,9,'873204','RADIOGRAFIA DE HOMBRO','2024-04-21 18:48:02','Atenció: 5956160\r\nFecha y Hora: 2024-04-20 09:59:00\r\n\r\n\r\n\r\nRADIOGRAFÍA DE HOMBRO DERECHO \r\n\r\nDisminución difusa en la densidad de las estructuras oseas visualizadas en relación con osteopenia-osteoporosis. \r\nFractura oblicua completa en el tercio medio de la diáfisis clavicular con desplazamiento de sus fragmentos principales en sentido cefálico. \r\nHipertrofia de la articulación acromio clavicular secundaria a cambios de tipo degenerativo.  \r\nNo se observan otras alteraciones en las estructuras óseas visualizadas.\r\nLas demás relaciones articulares se encuentran conservadas. \r\nNo hay particularidad en los tejidos blandos. \r\n\r\nCONCLUSIÓN: DISMINUCIÓN EN LA MINERALIZACIÓN ÓSEA.CAMBIOS HIPERTROFICOS DEGENERATIVOS DE LA ARTICULACIÓN ACROMIO CLAVICULAR. FRACTURA DE LA CLAVICULAR. \r\n','2024-04-22 11:49:35',NULL,1,1,'2024-05-16 22:44:39','2024-05-16 22:44:39'),(21,17,123,9,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-21 18:50:59','Atenció: 5956249\r\nFecha y Hora: 2024-04-20 10:00:11\r\n\r\nRADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL\r\n\r\n\r\n\r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nProyectadas sobre el tercio inferior del hemitórax derecho hacia los tejidos blandos de la pared torácica se observa imagen irregular bien definida radiopaca de 3 x 1 mm de diámetro correspondiente a cuerpo extraño.  \r\n\r\nCONCLUSIÓN: CUERPO EXTRAÑO RADIOPACO EN TEJIDOS BLANDOS DEL HEMITÓRAX DERECHO \r\n\r\n','2024-04-22 11:49:21',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(22,18,48,9,'873313','RADIOGRAFIA DE PIERNA AP Y LATERAL','2024-04-21 18:52:23','Atenció: 5956178\r\nFecha y Hora: 2024-04-20 10:06:08\r\n\r\nRADIOGRAFÍA DE PIERNA DERECHA \r\n\r\nEstudio técnicamente limitado por haber sido realizado a través de férula para inmovilización. \r\nMaterial quirúrgico en el tercio distal del peroné. \r\nDisminución difusa en la densidad de las estructuras oseas visualizadas en relación con osteopenia-osteoporosis. \r\nTejidos blandos no valorables.\r\nNo se observan otras alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\n\r\n\r\n','2024-04-22 11:49:04',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(23,19,50,9,'873333','RADIOGRAFIA DE PIE AP Y LATERAL','2024-04-21 18:53:39','Atenció: 5956181\r\nFecha y Hora: 2024-04-20 10:06:20\r\n\r\n\r\n\r\nRADIOGRAFÍA DE PIE IZQUIERDO \r\n\r\nNo se observan alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\nNo hay particularidad en los tejidos blandos. \r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE PIE IZQUIERDO DENTRO DE LÍMITES NORMALES.\r\n','2024-04-22 11:48:47',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(24,19,58,9,'873431','RADIOGRAFIA DE TOBILLO AP LATERAL Y ROTACION INTERNA','2024-04-21 18:53:19','Atenció: 5956181\r\nFecha y Hora: 2024-04-20 10:06:20\r\n\r\n\r\n\r\nRADIOGRAFÍA DE CUELLO DE PIE IZQUIERDO \r\n\r\nNo se observan alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\nNo hay particularidad en los tejidos blandos. \r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE CUELLO DE PIE IZQUIERDO DENTRO DE LÍMITES NORMALES.\r\n\r\n','2024-04-22 11:48:53',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(25,20,42,9,'873205','RADIOGRAFIA DE CODO','2024-04-21 18:56:06','Atenció: 5956199\r\nFecha y Hora: 2024-04-20 10:06:36\r\n\r\n\r\n\r\nRADIOGRAFÍA DE CODO IZQUIERDO \r\n\r\nFractura oblicua incompleta no desplazada en el tercio proximal del cúbito en localización metafisio -diafisiaria.\r\nNo se observan otras alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\nAumento en el espesor y la densidad de los tejidos blandos del codo por edema. \r\n\r\nCONCLUSIÓN: FRACTURA DEL TERCIO PROXIMAL DEL CÚBITO ASOCIADA A EDEMA DE TEJIDOS BLANDOS. \r\n','2024-04-22 11:48:39',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(26,21,18,9,'871010','RADIOGRAFIA DE COLUMNA CERVICAL','2024-04-21 18:57:29','Atenció: 5956202\r\nFecha y Hora: 2024-04-20 10:07:01\r\n\r\nRADIOGRAFÍA DE COLUMNA CERVICAL \r\n\r\nLa altura de los cuerpos vertebrales se encuentra conservada.\r\nLa amplitud y morfología de los espacios disco vertebrales no presenta alteración.\r\nElementos posteriores y agujeros de conjugación visualizados de aspecto radiológico normal.\r\nTejidos prevertebrales sin particularidad \r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE COLUMNA CERVICAL DENTRO DE LÍMITES NORMALES. \r\n','2024-04-22 11:48:03',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(27,21,123,9,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-21 18:58:27','Atenció: 5956202\r\nFecha y Hora: 2024-04-20 10:07:01\r\n\r\nRADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL\r\n\r\n\r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE TÓRAX DENTRO DE LÍMITES NORMALES.\r\n\r\n\r\n','2024-04-22 11:48:17',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(28,21,48,9,'873313','RADIOGRAFIA DE PIERNA AP Y LATERAL','2024-04-21 18:58:11','Atenció: 5956202\r\nFecha y Hora: 2024-04-20 10:07:01\r\n\r\n\r\n\r\nRADIOGRAFÍA DE PIERNA DERECHA \r\n\r\nNo se observan alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\nNo hay particularidad en los tejidos blandos. \r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE PIERNA DERECHA  DENTRO DE LÍMITES NORMALES.\r\n\r\n','2024-04-22 11:48:23',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(29,21,53,9,'873411','RADIOGRAFIA DE PELVIS O CADERA O ARTICULACION COXO FEMORAL AP LATERAL','2024-04-21 18:58:16','Atenció: 5956202\r\nFecha y Hora: 2024-04-20 10:07:01\r\n\r\nRADIOGRAFÍA DE PELVIS \r\n\r\nNo se observan alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\nNo hay particularidad en los tejidos blandos. \r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE PELVIS DENTRO DE LÍMITES NORMALES.\r\n\r\n','2024-04-22 11:48:30',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(30,22,22,9,'871040','RADIOGRAFIA DE COLUMNA LUMBOSACRA','2024-04-21 18:59:40','Atenció: 5956231\r\nFecha y Hora: 2024-04-20 10:07:18\r\n\r\n\r\nRADIOGRAFÍA DE COLUMNA LUMBAR \r\n\r\nActitud escoliótica lumbar superior de vértice derecho. \r\nLa altura de los cuerpos vertebrales se encuentra conservada.\r\nLa amplitud y morfología de los espacios disco vertebrales no presenta alteración.\r\nElementos posteriores y agujeros de conjugación visualizados de aspecto radiológico normal.\r\nTejidos prevertebrales sin particularidad \r\n\r\nCONCLUSIÓN: ACTITUD ESCOLIOTICA LUMBAR. ','2024-04-22 11:47:50',NULL,1,1,'2024-05-16 22:44:40','2024-05-16 22:44:40'),(31,23,93,9,'883220','RESONANCIA NUCLEAR MAGNETICA DE COLUMNA TORACICA SIMPLE','2024-04-20 11:31:35','Atenció: 5942798\r\nFecha y Hora: 2024-04-20 11:28:55\r\n\r\n\r\n\r\nRESONANCIA MAGNÉTICA COLUMNA DORSAL\r\n\r\nTécnica:\r\nSe practicaron secuencias con técnica FSE e inversión recuperación obteniendo imágenes en los planos axial,\r\nsagital y coronal potenciadas en T1, T2 y STIR.\r\n\r\nHallazgos:\r\nIncipiente formación de osteofitos marginales anteriores en cuerpos vertebrales dorsales.\r\nEn imágenes sagitales T2 se observa ligera disminución difusa la intensidad de señal de los discos\r\nintervertebrales dorsales a nivel medial-inferior por deshidratación.\r\nLa intensidad de señal y la morfología de los discos intervertebrales son normales.\r\nLa intensidad de señal y la morfología de los cuerpos vertebrales y los elementos posteriores tienen aspecto\r\nnormal. La amplitud de los agujeros de conjugación así como la del canal raquídeo es satisfactoria.\r\nEl cordón medular presenta una intensidad de señal y morfología normal y no se identifican masas o colecciones\r\nintra ni extradurales. No se aprecian alteraciones en los tejidos blandos peri-vertebrales.\r\n\r\nCONCLUSIÓN: Incipientes osteofitos en cuerpos vertebrales dorsales. Deshidratación discal intervertebral dorsal\r\nsecundaria a cambios de tipo degenerativo.\r\n','2024-04-20 11:31:58',NULL,1,1,'2024-05-16 22:44:41','2024-05-16 22:44:41'),(32,23,95,9,'883230','RESONANCIA NUCLEAR MAGNETICA DE COLUMNA LUMBOSACRA SIMPLE','2024-04-20 11:30:40','Atenció: 5942798\r\nFecha y Hora: 2024-04-20 11:28:55\r\n\r\nRESONANCIA NUCLEAR MAGNETICA DE COLUMNA LUMBOSACRA SIMPLE\r\n\r\nResonancia magnética de columna lumbar:\r\n\r\nTécnica:\r\nSe practicaron secuencias con técnica FSE e inversión recuperación obteniendo imágenes en los planos axial,\r\nsagital y coronal potenciadas en T1, T2 y STIR.\r\n\r\nHallazgos:\r\nIncipientes osteofitos marginales anteriores en cuerpos vertebrales lumbares.\r\nEn imágenes sagitales T2 se observa ligera disminución difusa la intensidad de señal del disco intervertebral en\r\nel nivel de L3-L4 por deshidratación secundaria a cambios de tipo degenerativo.\r\nEn imágenes sagitales T2 se observa disminución difusa de intensidad de señal y pérdida de altura del disco\r\nintervertebral en el nivel de L5-S1 por discopatía. Abombamiento discal asimétrico en el nivel de L5-S1 borra la\r\ngrasa peridural adyacente condicionando compromiso foraminal parcial bilateral en donde entra en contacto con\r\nla raíces nerviosas emergentes correspondientes.\r\nIncremento difuso en la intensidad de señal del platillo inferior del cuerpo vertebral de L5 y aspecto superior de\r\nS1 evidente tanto en imágenes en T1 como en T2 por espondilosis tipo Modic 2.\r\nDesplazamiento en sentido anterior del cuerpo vertebral de L5 con respecto a S1 de aproximadamente un 15%\r\npor anterolistesis grado I.\r\nArtificios por susceptibilidad magnética en cuerpos vertebrales y elementos posteriores de L5 y S1 en relación\r\ncon presencia de material quirúrgico.\r\nLa intensidad de señal y la morfología de los demás discos intervertebrales son normales.\r\nLa altura de los cuerpos vertebrales se encuentra conservada y los elementos posteriores restantes tienen\r\naspecto normal.\r\nLa amplitud de los otros agujeros de conjugación así como la del canal raquídeo es satisfactoria.\r\nEl cono medular y las raíces de la cola de caballo tienen aspecto usual.\r\nNo se aprecian alteraciones en los tejidos blandos peri-vertebrales.\r\n\r\nCONCLUSIÓN: Incipientes osteofitos en cuerpos vertebrales lumbares. Cambios por espondilosis en cuerpos\r\nvertebrales de L5 y S1. Deshidratación discal intervertebral en el nivel de L3-L4 secundaria a cambios de tipo\r\ndegenerativo. Discopatía y abombamiento discal intervertebral en el nivel de L5-S1. Anterolistesis de L5 grado I.\r\nMaterial quirúrgico en el nivel de L5-S1.','2024-04-20 11:32:03',NULL,1,1,'2024-05-16 22:44:41','2024-05-16 22:44:41'),(33,24,77,5,'879301','TOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE','2024-04-20 13:56:41','Atenció: 5955667\r\nFecha y Hora: 2024-04-20 13:54:36\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE\r\n\r\nTÉCNICA\r\nSe realizaron cortes desde la entrada al tórax hasta los hemidiafragmas con reconstrucciones en los planos axial y coronal sin administrar medio de contraste endovenoso . Se toman registro en ventana de parénquima pulmonar y de mediastino.\r\n\r\nHALLAZGOS\r\nEl coeficiente de atenuación de los parénquimas pulmonares es normal sin evidencia de lesiones en estos ni alteraciones pleurales.\r\nEstudio limitado para evaluar realce de estructuras mediastinales por ausencia de contraste I.V, sin embargo no se observan masas,\r\ncolecciones o adenomegalias mediastinales. La vía aérea presenta curso y calibre normal.\r\nCorazón de tamaño normal. No se observa líquido pericárdico ni engrosamiento anormal de este.\r\nAorta torácica de calibre normal. Tronco de la arteria pulmonar de 23 mm.\r\nCambios espondilosicos de la columna torácica; tejidos blandos de la pared del tórax sin alteraciones.\r\nPorción evaluada del abdomen no se demuestran alteraciones.\r\n\r\nCONCLUSIÓN\r\nCambios espondilosicos de la columna torácica, resto del estudio dentro de limites normales.','2024-04-20 13:57:08',NULL,1,1,'2024-05-16 22:44:41','2024-05-16 22:44:41'),(34,25,65,5,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-20 13:56:01','Atenció: 5956421\r\nFecha y Hora: 2024-04-20 13:55:14\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nEstudio escanográfico realizado con adquisición helicoidal axial desde la base del craneo y hasta el vértex.\r\n\r\nHALLAZGOS\r\nPARENQUIMA NERVIOSO: El parénquima nervioso visualizado de ambos hemisferios cerebrales es de apariencia normal, sin que se\r\ndemuestren lesiones focales. No hay signos de calcificación o hemorragia.\r\nLas estructuras parenquimatosas de la fosa posterior tienen apariencia habitual.\r\nVENTRICULOS: El sistema ventricular es de tamaño y forma normal, localizado en posición central.\r\nESPACIO EXTRAAXIAL: Las cisternas basales y la amplitud del espacio subaracnoideo son de características usuales. Se descartan\r\ncolecciones extra axiales compresivas.\r\nESTRUCTURAS EXTRACRANEALES: Las diferentes cavidades neumatizadas de la base del cráneo no presentan alteración.\r\n\r\nCONCLUSIÓN\r\nESCANOGRAFIA CEREBRAL SIMPLE DENTRO DE LIMITES NORMALES.\r\n','2024-04-20 13:57:02',NULL,1,1,'2024-05-16 22:44:41','2024-05-16 22:44:41'),(35,26,77,5,'879301','TOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE','2024-04-20 14:01:23','Atenció: 5955445\r\nFecha y Hora: 2024-04-20 13:59:38\r\n\r\nANGIOTAC DE TORAX POR TEP \r\n\r\nTÉCNICA\r\nEn equipo multidetector, empleando técnica helicoidal y tras la administración demedio de contraste hidrosoluble empleando técnica helicoidal con multidetectores y reconstrucciones con algoritmo de reconstrucción y ventana tanto para estructuras mediastinales como parénquima pulmonar. Se realizan reconstrucciones en el plano coronal.\r\n\r\nHALLAZGOS\r\nAdecuada opacificación de las arterias pulmonares centrales, lobares y segmentarias sin defectos en su interior que sugieran la presencia de trombos.\r\nDerrames pleurales bilaterales de aspecto libre con escasa cantidad. Bandas parenquimatosas en lóbulos inferiores.\r\nCardiomegalia global. Aorta torácica de calibre normal.\r\nNo se observan masas ni adenomegalias mediastinales.\r\nLa vía aérea presenta curso y calibre normal.\r\nLa porción valorada de la base del cuello y del hemiabdomen superior es normal.\r\nEscoliosis torácica de convexidad derecha y aumento de la cifosis fisiológica, tejidos blandos de la pared del tórax sin alteraciones.\r\n\r\nCONCLUSIÓN\r\nEstudio negativo para tromboembolismo pulmonar.\r\nDerrames pleurales bilaterales leves de aspecto libre .','2024-04-20 14:03:00',NULL,1,1,'2024-05-16 22:44:41','2024-05-16 22:44:41'),(36,27,80,5,'879420','TOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL','2024-04-20 14:02:01','Atenció: 5956225\r\nFecha y Hora: 2024-04-20 14:00:29\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL CONTRASTADA \r\n\r\nTÉCNICA\r\nSe realizaron cortes axiales tomográficos computarizados empleando técnica helicoidal realizando reconstrucciones de 3 mm, después de la administración del medio de contraste oral y endovenoso. Se realizaron reconstrucciones coronal y sagital.\r\n\r\nHALLAZGOS\r\nEl hígado presenta tamaño, contornos y densidad normal sin que se observen en él lesiones focales.\r\nLa vesícula biliar presente, distendida, de paredes delgadas y contenido homogéneo; la vía biliar intra y extra hepática es de calibre\r\nnormal.\r\nEl páncreas, el bazo y las glándulas suprarrenales son de morfología, tamaño, densidad y patrón de realce usual, no presentan lesiones focales.\r\nLos riñones tienen tamaño, posición y realce normal; no hay dilatación de sistemas colectores. Uréteres de calibre y curso normal. Vejiga distendida sin alteraciones en su interior.\r\nÚtero y anexos de tamaño, morfología y densidad normal.\r\nAdecuado paso del medio de contraste por los diferentes segmentos del tracto gastrointestinal observados sin engrosamientos anormales de su pared ni compresiones extrínsecas. Múltiples divertículos del colon descendente y sigmoides sin cambios inflamatorios.\r\nNo hay alteración en la densidad de la grasa ni adenomegalias mesentéricas. No hay líquido libre en cavidad.\r\nAorta y vena cava inferior de curso y calibre normal. No se observan masas ni adenomegalias retroperitoneales.\r\nPequeña hernia umbilical de contenido graso.\r\nCambios degenerativos de la columna lumbar con espondilosis y anterolistesis de L4 sobre L5.\r\n\r\nCONCLUSIÓN\r\nEnfermedad diverticular del colon descendente y sigmoides sin cambios inflamatorios.\r\nPequeña hernia umbilical de contenido graso.\r\nCambios degenerativos de la columna lumbar con espondilosis y anterolistesis de L4 sobre L5.','2024-04-20 14:02:28',NULL,1,1,'2024-05-16 22:44:41','2024-05-16 22:44:41'),(37,28,80,5,'879420','TOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL','2024-04-20 16:24:22','Atenció: 5955826\r\nFecha y Hora: 2024-04-20 16:21:57\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL CONTRASTADO \r\n\r\nTÉCNICA\r\nCon técnica helicoidal se realiza TAC de la totalidad del abdomen tal como se indica en la radiografía digital se administra medio de contraste I.V yodado no iónico hidrosoluble en bolo y medio de contraste V.O.\r\n\r\nHALLAZGOS\r\nÁreas de neumoperitoneo generalizado en abdomen con liquido libre peri hepático, periesplenico y en pelvis.\r\nÁrea focal de neumoperitoneo adyacente a cara posterior del colón trasverso en ángulo hepático, ruptura de asa?\r\nEl hígado se observa de tamaño, forma, contornos y densidad normales, no hay lesiones focalizadas.\r\nNo hay dilatación de la via biliar intra ni extrahepatica. La vesicula es de apariencia escanografica usual.\r\nEl páncreas, el bazo, los riñones y las suprarenales son normales. Quiste cortical renal simple de 30x35 mm en región interpolar derecha y de 22 mm en región interpolar izquierda.\r\nNo hay dilatación de los sistemas colectores renales. La vejiga es normal.\r\nAorta, vena cava inferior y demás estructuras vasculares observadas son de curso calibre normal.\r\nCambios espondilosicos de la columna toracica.\r\n\r\nONCLUSIÓN\r\nÁreas de neumoperitoneo generalizado en abdomen con liquido libre peri hepático, periesplenico y en pelvis.\r\nÁrea focal de neumoperitoneo adyacente a cara posterior del colón trasverso en ángulo hepático, ruptura de asa?\r\nNOTA: Estudio con hallazgos críticos que requiere evaluación inmediata por el médico tratante','2024-04-20 16:24:57',NULL,1,1,'2024-05-16 22:44:41','2024-05-16 22:44:41'),(38,29,65,5,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-20 16:23:59','Atenció: 5956474\r\nFecha y Hora: 2024-04-20 16:22:42\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nEstudio escanográfico realizado con adquisición helicoidal axial desde la base del craneo y hasta el vértex.\r\n\r\nHALLAZGOS\r\nPARENQUIMA NERVIOSO: El parénquima nervioso visualizado de ambos hemisferios cerebrales es de apariencia normal, sin que se demuestren lesiones focales. No hay signos de calcificación o hemorragia.\r\nLas estructuras parenquimatosas de la fosa posterior tienen apariencia habitual.\r\nVENTRICULOS: El sistema ventricular es de tamaño y forma normal, localizado en posición central.\r\nESPACIO EXTRAAXIAL: Las cisternas basales y la amplitud del espacio subaracnoideo son de características usuales. Se descartan colecciones extra axiales compresivas.\r\nESTRUCTURAS EXTRACRANEALES: Las diferentes cavidades neumatizadas de la base del cráneo no presentan alteración.\r\n\r\nCONCLUSIÓN\r\nNo se observan masas ni hemorragias intracraneales.','2024-04-20 16:24:49',NULL,1,1,'2024-05-16 22:44:42','2024-05-16 22:44:42'),(39,30,77,5,'879301','TOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE','2024-04-20 16:23:33','Atenció: 5956160\r\nFecha y Hora: 2024-04-20 16:23:02\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE\r\n\r\nTÉCNICA\r\nCon técnica helicoidal se realiza TAC simple de la totalidad del tórax, tal como lo indica la radiografía digital.\r\n\r\nHALLAZGOS\r\nLas estructuras vasculares mediastinales son de curso y calibre normales.\r\nCorazón de apariencia escanográfica usual.\r\nTraquea y bronquios fuentes normales.\r\nAtelectasia subsegmentaria en lóbulo inferior izquierdo.\r\nEspacios pleurales libres\r\nCambios espondilosicos de la columna torácica.\r\n\r\nCONCLUSIÓN\r\nAtelectasia subsegmentaria en lóbulo inferior izquierdo.\r\nCambios espondilosicos de la columna torácica.','2024-04-20 16:24:44',NULL,1,1,'2024-05-16 22:44:42','2024-05-16 22:44:42'),(40,31,65,5,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-20 20:51:29','Atenció: 5956552\r\nFecha y Hora: 2024-04-20 20:51:07\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nEstudio escanográfico que se realizó en cortes axiales desde la base del cráneo al vértex.\r\n\r\nHALLAZGOS\r\nHipodensidad de la sustancia blanca de ambos hemisferios cerebrales.\r\nÁrea de encefalomalacia frontal izquierda.\r\nHipodensidad mal definida con perdida de la diferenciación sustancia blanca sustancia gris temporo-parietal izquierda.\r\nDisminución global el volumen parenquimatoso con prominencia del espacio subaracnoideo y ventriculomegalia.\r\nLas estructuras de la fosa posterior tienen apariencia habitual.\r\nSe descartan colecciones extra axiales compresivas.\r\nLas diferentes cavidades neumatizadas de la base del cráneo no presentan alteración.\r\n\r\nCONCLUSIÓN\r\nEvento isquemico agudo parietotemporal derecho.\r\nÁrea de encefalomalacia frontal izquierda.\r\nNo se observan hemorragias intracraneales.\r\nCambios de leucoencefalopatia cronica isquemica.','2024-04-20 20:51:51',NULL,1,1,'2024-05-16 22:44:42','2024-05-16 22:44:42'),(41,32,65,5,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-20 22:35:44','Atenció: 5956631\r\nFecha y Hora: 2024-04-20 22:33:46\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nSe valora tomografia de craneo simple adquisición axial desde la base del cráneo a la convexidad, con reconstrucciones coronal y sagital, identificando lo siguiente:\r\n\r\nHALLAZGOS\r\nLínea media central.\r\nVentrículos laterales y surcos corticales prominentes.\r\nNo hay colecciones intra o extra-axiales. No hay lesiones expansivas intracraneanas.\r\nSe observan calcificaciones en la porción cavernosa de las carótidas internas.\r\nSe observa disminución en el espesor de las circunvoluciones de manera difusa, se conserva diferenciación sustancia gris/blanca.\r\nNo hay hipo-densidades que sugieran la presencia de isquemia o infarto.\r\nNo hay evidencia de hemorragia subaracnoidea.\r\nNo hay líneas de fractura o lesiones líticas o blásticas.\r\nSe observa opacificación parcial de las celdillas etmoidales y senos maxilares con niveles de atenuacion de hasta 8U.H, no hay cambios inflamatorios en lo incluido de los demas senos paranasales o celdillas mastoideas.\r\n\r\nCONCLUSIÓN\r\nDisminucion global del volumen parenquimatoso, se sugiere correlación clínica, a considerar cambios involutivos por la edad entre las causas probables.\r\nEnfermedad vascular arterioesclerotica.\r\nOpacificación parcial de las celdillas etmoiddales y senos maxilares, se sugiere correlación clínica, considerar máxiloetmoiditis\r\n','2024-04-20 22:36:11',NULL,1,1,'2024-05-16 22:44:42','2024-05-16 22:44:42'),(42,33,77,5,'879301','TOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE','2024-04-20 22:35:16','Atenció: 5956117\r\nFecha y Hora: 2024-04-20 22:34:04\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE\r\n\r\nTÉCNICA\r\nSe valora tomografía de tórax simple desde el estrecho torácico superior hasta las cúpulas diafragmáticas adquisición axial con reconstrucción multiplanar, identificando lo siguiente:\r\n\r\nHALLAZGOS\r\nPiel y tejidos blandos de densidad normal.\r\nTejido óseo sin evidencia de lesiones líticas, blásticas ni fracturas. Los cuerpos vertebrales de la columna dorsal conservan forma, densidad y altura.\r\nGlándula tiroides de aspecto normal.\r\nNo se identifican adenomegalias axilares, mediastinales ni hiliares.\r\nCorazón de aspecto normal. No se observa aumento del liquido pericárdico.\r\nAorta de trayecto normal, sin alteraciones. Tronco pulmonar mide 21 mm.\r\nTráquea central de calibre normal, bronquios principales simétricos.\r\nSe identifica aumento del liquido pleural apicobasal que condiciona atelectasia pasiva del lobulo inferior y disminucion en el volumen del lobulo superior.\r\nParénquima pulmonar izquierdo sin evidencia de consolidaciones, masas o lesiones quísticas.\r\nDiafragma sin solución de continuidad de espesor normal.\r\nEn lo valorable de las estructuras intrabdominales no se observan alteraciones\r\n´\r\nCONCLUSIÓN\r\nDerrame pleural derecho que condiciona disminucion en el volumen del lobulo superior y atelectasia pasiva del lobulo inferior; derechos, se sugiere correacion clinica y con antecedentes.\r\n','2024-04-20 22:36:07',NULL,1,1,'2024-05-16 22:44:42','2024-05-16 22:44:42'),(43,34,80,NULL,'879420','TOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL',NULL,NULL,NULL,NULL,1,0,'2024-05-16 22:44:42','2024-05-16 22:44:42'),(44,35,80,5,'879420','TOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL','2024-04-21 06:18:26','Atenció: 5954965\r\nFecha y Hora: 2024-04-21 06:17:16\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL CONTRASTADA \r\n\r\nTÉCNICA\r\nSe valora tomografía de abdomen contrastada, empleando contraste iodado hidrosoluble IV adquisición axial, con reconstrucciones coronal y sagital, identificando lo siguiente:\r\n\r\nHALLAZGOS\r\nSe observa pequeño defecto herniario umbilical de 3 mm, con protrusión de tejido graso.\r\nEn lo valorable de las bases pulmonares sin evidencia de consolidaciones, masas, nódulos o atelectasia. No se observa derrame pleural, ni neumotórax. Línea pleural delgada.\r\nDiafragma integro, de espesor normal.\r\nHígado en situación, de forma y tamaño normal, índice de 13cm, atenuación parenquimatosa homogénea, realce uniforme, sin evidencia de lesiones solidas o quísticas.\r\nNo se observa dilatación de las vías biliares intra o extrahepáticas.\r\nVesícula biliar adecuadamente distendida, pared delgada con realce uniforme, interior de densidad homogénea sin evidencia de litos de alta densidad.\r\nBazo en situación y de forma normal, aumentado de tamaño, mide 13 cm, sin evidencia de lesiones quísticas ni solidas. No se observan esplenúnculos.\r\nGlándulas suprarrenales conservan forma en Y, de tamaño y densidad normal.\r\nPáncreas en posición y de tamaño normal, parénquima sin evidencia de lesiones quísticas ni sólidas, realce homogéneo, conducto pancreático no dilatado, grasa peri pancreática nítida.\r\nRiñones en posición de forma y tamaño normal, parénquima con adecuada diferenciación corticomedular, realce simétrico, sin evidencia de lesiones quísticas ni sólidas, ni presencia de calcificaciones. No se identifica dilatación calicial ni de la pelvis renal, no se observan litos.\r\nUréteres no dilatados, sin presencia de litos.\r\nVejiga adecuadamente distendida, interior hipodenso, pared delgada.\r\nUtero y anexos de forma y densidad normal.\r\nAorta y vena cava inferior de trayecto normal.\r\nNo se observan adenopatías.\r\nEstomago parcialmente distendido, la pared delgada .\r\nDuodeno e intestino delgado de disposición habitual, adecuadamente distendido, pared delgada.\r\nColon y recto de disposición habitual, conserva patrón haustral, pared delgada. Se visualzia apendice cecal delgada con gas en su interior.\r\nNo se identifica liquido libre.\r\nTejido óseo de densidad normal, sin evidencia de lesiones líticas, blásticas ni fracturas.\r\nEn lo valorable de la columna lumbar los cuerpos vertebrales conservan su forma y altura, los espacios intervertebrales conservan su altura, no se observan datos de estenosis del canal vertebral ni de los neuro-forámenes.\r\n\r\nCONCLUSIÓN\r\nEsplenomegalia.\r\nHernia umbilical.','2024-04-21 06:18:55',NULL,1,1,'2024-05-16 22:44:43','2024-05-16 22:44:43'),(45,36,80,6,'879420','TOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL','2024-04-21 12:06:54','Atenció: 5956708\r\nFecha y Hora: 2024-04-21 11:57:41\r\n\r\nUROTAC\r\n\r\nTÉCNICA\r\nEstudio realizado en tomógrafo multicorte, adquisición de imágenes axiales en forma simple desde las bases pulmonares hasta la sínfisis del pubis, con posteriores reconstrucciones multiplanares.\r\nHALLAZGOS\r\nLos riñones se encuentran en posición usual, son de forma, tamaño y densidad simple normales.\r\nLeve dilatación pielocalicial del riñón izquierdo, secundario a la presencia de cálculo en la unión urterovesical de 3 mm.\r\nLos uréteres son de curso y calibre normales.\r\nLa vejiga distiende parcialmente de paredes delgadas.\r\nLo visualizado del hígado, bazo, páncreas y glándulas suprarrenales son de forma, tamaño y densidad simples normales.\r\nNo hay líquido libre en la cavidad abdominal.\r\nPared del abdomen sin alteración.\r\nEstructuras óseas en límites normales.\r\nCONCLUSIÓN\r\nCálculo en la unión urterovesical izquierda con leve efecto obstructivo asociado.','2024-04-21 12:11:02',NULL,1,1,'2024-05-16 22:44:43','2024-05-16 22:44:43'),(46,37,80,6,'879420','TOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL','2024-04-21 12:07:34','Atenció: 5956648\r\nFecha y Hora: 2024-04-21 11:58:16\r\n\r\nUROTAC\r\n\r\nTÉCNICA\r\nEstudio realizado en tomógrafo multicorte, adquisición de imágenes axiales en forma simple desde las bases pulmonares hasta la sínfisis del pubis, con posteriores reconstrucciones multiplanares.\r\n\r\nHALLAZGOS\r\nLos riñones se encuentran en posición usual, son de forma, tamaño y densidad simple normales.\r\nNo se identifican dilataciones en sistemas pielocaliciales.\r\nLos uréteres son de curso y calibre normales.\r\nLa vejiga distiende adecuadamente de paredes engrosadas.\r\nLo visualizado del hígado, bazo, páncreas y glándulas suprarrenales son de forma, tamaño y densidad simples normales.\r\nPequeño quiste de aspecto simple hepático hipodenso de pared fina.\r\nNo hay líquido libre en la cavidad abdominal.\r\nPequeña hernia inguinal indirecta izquierda, y periumbilical de contenido graso.\r\nDiastasis de los músculos rectos abdominales.\r\nRuptura degenerativa de la pars interarticularis del nivel L5 S1 con espondilolistesis grado I-II de L5 sobre S1 con signos de discopatía y luxación facetaria con bloqueo.\r\nCONCLUSIÓN\r\nPequeña hernia inguinal indirecta izquierda, y periumbilical de contenido graso.\r\n','2024-04-21 12:10:52',NULL,1,1,'2024-05-16 22:44:43','2024-05-16 22:44:43'),(47,38,71,6,'879131','TOMOGRAFIA AXIAL COMPUTADA DE SENOS PARANASALES O CARA CORTES AXIALES Y CORONALES','2024-04-21 12:06:10','Atenció: 5956703\r\nFecha y Hora: 2024-04-21 11:58:52\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CARA\r\n\r\nTÉCNICA\r\nSe realizaron cortes finos en los planos axial y coronal con énfasis sobre la región facial.\r\nHALLAZGOS\r\nLas diferentes estructuras óseas visualizadas tienen apariencia habitual sin lesiones traumáticas. En especial no se registran\r\nalteraciones de rebordes orbitarios anteriores.\r\nEl septum nasal ocupa una posición central. Los cornetes son de tamaño y configuración normales y no se identifican lesiones focales al interior de las cavidades nasales.\r\nLa transparencia y neumatización de las cavidades paranasales tienen apariencia habitual, sin evidencia de engrosamiento mucoso o niveles hidroaéreos. Los complejos ostiomeatales y recesos esfeno etmoidales se encuentran libres.\r\nLos tejidos blandos de la nasofaringe no presentan alteración.\r\nEdema y enfisema de los tejidos blandos epicraneanos en la región periorbitaria derecha.\r\nCONCLUSIÓN\r\nEdema y enfisema de los tejidos blandos epicraneanos en la región periorbitaria derecha.','2024-04-21 12:10:41',NULL,1,1,'2024-05-16 22:44:43','2024-05-16 22:44:43'),(48,39,80,6,'879420','TOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL','2024-04-21 12:04:42','Atenció: 5956623\r\nFecha y Hora: 2024-04-21 11:59:17\r\n\r\nUROTAC\r\n\r\nTÉCNICA\r\nEstudio realizado en tomógrafo multicorte, adquisición de imágenes axiales en forma simple desde las bases pulmonares hasta la sínfisis del pubis, con posteriores reconstrucciones multiplanares.\r\nHALLAZGOS\r\nRiñón derecho aumentado de tamaño, con aspecto de pseudo masa, con dilatación pielocalicial generalizada, acompañada de formaciones pseudo diverticulares y presencia de fragmentos con densidad cálcica en el grupo colector superior, el de mayor tamaño de 27 mm.\r\nDilatación del uréter en todo su trayecto, secundaria la presencia de cálculos de contornos irregulares, fusiformes, el de mayor tamaño de 27 mm en sentido craneocaudal, con espesor máximo de 9 mm.\r\nExiste engrosamiento de las paredes del uréter distal.\r\nLa vejiga distiende parcialmente, de paredes delgadas.\r\nLo visualizado del hígado, bazo, páncreas y glándulas suprarrenales son de forma, tamaño y densidad simples normales.\r\nNo hay líquido libre en la cavidad abdominal.\r\nPared del abdomen sin alteración.\r\nEstructuras óseas en límites normales.\r\nCONCLUSIÓN\r\nEvaluar la presencia de pielonefritis xanto granulomatosa derecha, con cálculos en el grupo colector superior y dilatación del uréter del mismo lado con cálculos asociados.','2024-04-21 12:10:21',NULL,1,1,'2024-05-16 22:44:43','2024-05-16 22:44:43'),(49,40,65,6,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-21 12:05:25','Atenció: 5956706\r\nFecha y Hora: 2024-04-21 11:59:45\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nEstudio realizado en tomógrafo multicorte, adquisición de imágenes axiales desde la base hasta el vertex\r\nHALLAZGOS\r\nNo se identifican colecciones intra o extra axiales compresivas al momento de la evaluación.\r\nLos coeficientes de atenuación del parénquima nervioso se encuentran conservados.\r\nLa forma, tamaño y disposición del sistema ventricular, y de las estructuras que contienen líquido cefalorraquideo son de densidad normales.\r\nGanglios de la base, tallo y fosa posterior de apariencia usual para la edad.\r\nLas órbitas y su contenido no presentan alteraciones.\r\nEl patrón de neumatización de las cavidades paranasales, celdillas mastoideas y pirámides petrosas es normal.\r\nCONCLUSIÓN\r\nESTUDIO EN LÍMITES NORMALES','2024-04-21 12:09:58',NULL,1,1,'2024-05-16 22:44:43','2024-05-16 22:44:43'),(50,41,65,6,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-21 12:02:41','Atenció: 5956695\r\nFecha y Hora: 2024-04-21 12:00:04\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nEstudio realizado en tomógrafo multicorte, adquisición de imágenes axiales desde la base hasta el vertex\r\n\r\nHALLAZGOS\r\nNo se identifican colecciones intra o extra axiales compresivas al momento de la evaluación.\r\nLos coeficientes de atenuación del parénquima nervioso se encuentran conservados.\r\nLa forma, tamaño y disposición del sistema ventricular, y de las estructuras que contienen líquido cefalorraquideo son de densidad normales.\r\nGanglios de la base, tallo y fosa posterior de apariencia usual para la edad.\r\nLas órbitas y su contenido no presentan alteraciones.\r\nEl patrón de neumatización de las cavidades paranasales, celdillas mastoideas y pirámides petrosas es normal.\r\nEdema y enfisema de los tejidos blandos epicraneanos en la región parietal izquierda.\r\nNódulo ovalado sólido subdérmico temporal derecho de 15 mm con calcificación gruesa en su interior, puede corresponder con dermoide a este nivel.\r\n\r\nCONCLUSIÓN\r\nEdema y enfisema de los tejidos blandos epicraneanos en la región parietal izquierda.','2024-04-21 12:09:49',NULL,1,1,'2024-05-16 22:44:44','2024-05-16 22:44:44'),(51,42,71,6,'879131','TOMOGRAFIA AXIAL COMPUTADA DE SENOS PARANASALES O CARA CORTES AXIALES Y CORONALES','2024-04-21 12:03:10','Atenció: 5956695\r\nFecha y Hora: 2024-04-21 12:00:14\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE  CARA CORTES AXIALES Y CORONALES\r\n\r\nTÉCNICA\r\nSe realizaron cortes finos en los planos axial y coronal con énfasis sobre la región facial.\r\nHALLAZGOS\r\nLas diferentes estructuras óseas visualizadas tienen apariencia habitual sin lesiones traumáticas. En especial no se registran\r\nalteraciones de rebordes orbitarios anteriores.\r\nEl septum nasal es sinuoso con curva dominante a la izquierda. Los cornetes son de tamaño y configuración normales y no se identifican lesiones focales al interior de las cavidades nasales.\r\nLa transparencia y neumatización de las cavidades paranasales tienen apariencia habitual, sin evidencia de engrosamiento mucoso o niveles hidroaéreos. Los complejos ostiomeatales y recesos esfeno etmoidales se encuentran libres.\r\nLos tejidos blandos de la nasofaringe no presentan alteración.\r\nCONCLUSIÓN\r\nSeptum nasal sinuoso.\r\n','2024-04-21 12:09:33',NULL,1,1,'2024-05-16 22:44:44','2024-05-16 22:44:44'),(52,43,65,6,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-21 12:12:20','Atenció: 5956774\r\nFecha y Hora: 2024-04-21 12:08:55\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nEn tomógrafo multicorte se adquieren imágenes desde el vértex hasta la base de cráneo con reconstrucción en ventana de tejido blando y hueso.\r\nHALLAZGOS\r\nHipodensidad de la sustancia blanca de ambos hemisferios cerebrales.\r\nHipodensidad córtico subcortical frontal izquierda afectando principalmente el giro pre central.\r\nDisminución global el volumen parenquimatoso con prominencia del espacio subaracnoideo y ventriculomegalia de predominio supratentorial, con acueducto y 4º ventrículo tamaño normales.\r\nLas estructuras de la fosa posterior tienen apariencia habitual.\r\nSe descartan colecciones extra axiales compresivas.\r\nLas diferentes cavidades neumatizadas de la base del cráneo no presentan alteración.\r\n\r\nCONCLUSIÓN\r\nCambios de leucoencefalopatía probablemente microangiopática hipertensiva y/o arterioesclerótica.\r\nInfarto en el giro pre central izquierdo.','2024-04-21 12:13:39',NULL,1,1,'2024-05-16 22:44:44','2024-05-16 22:44:44'),(53,44,77,6,'879301','TOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE','2024-04-21 12:12:58','Atenció: 5956774\r\nFecha y Hora: 2024-04-21 12:09:06\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE\r\n\r\nTÉCNICA\r\nEstudio realizado en tomógrafo multicorte, de manera simple, adquisición de imágenes axiales desde el opérculo torácico hasta las bases pulmonares.\r\nHALLAZGOS\r\nTronco principal de la arteria pulmonar con diámetro transverso de 39 mm (aumentado).\r\nCrecimiento global de cavidades cardíacas, no hay derrame pericárdico.\r\nNo se identifican masas o conglomerados ganglionares en el mediastino.\r\nTráquea y grandes bronquios permeables.\r\nEngrosamiento liso de septos interlobulillares con opacidades acinares en la porción declive de ambos hemitórax.\r\nDerrames pleurales bilaterales.\r\nPared del tórax sin alteración.\r\nCONCLUSIÓN\r\nCardiomegalia global, con signos de hipertensión pulmonar arterial.\r\nConsiderar edema pulmonar en contexto clínico apropiado.\r\nEngrosamiento liso de septos interlobulillares y derrames pleurales bilaterales en moderada cantidad, para correlación con el balance hídrico.\r\n','2024-04-21 12:13:34',NULL,1,1,'2024-05-16 22:44:44','2024-05-16 22:44:44'),(54,45,85,10,'879910','TOMOGRAFIA AXIAL COMPUTADA EN RECONSTRUCCION TRIDIMENSIONAL','2024-04-21 15:15:37','Atenció: 5956163\r\nFecha y Hora: 2024-04-21 15:13:21\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA EN RECONSTRUCCION TRIDIMENSIONAL\r\n\r\n\r\nTÉCNICA\r\n\r\nSe practicaron cortes axiales computarizados con colimación de 1.2 mm, con reconstrucciones en los planos axial y coronal cada 3 mm desde el polo superior de los riñones hasta la sínfisis púbica sin administración de material de contraste.  \r\n\r\nHALLAZGOS\r\nLos riñones tienen forma, tamaño, contornos, densidad y localización normal, sin evidencia de lesiones hiperdensas con densidad cálcicaque indiquen la presencia de cálculos. No hay alteración de la densidad de la grasa perirenal.\r\nNo hay dilatación de sistemas colectores y los uréteres tienen calibre y curso normal sin que se demuestren defectos hiperdensos en suinterior.\r\nVejiga de contornos regulares, sin alteraciones en su interior.\r\nPróstata y vesículas seminales de morfología y densidad normal.\r\nEstudio limitado para evaluar órganos sólidos y asas intestinales por ausencia de contraste IV y oral sin embargo estas no señalan particularidad. La densidad del mesenterio es normal y no hay líquido libre en cavidad abdominal.\r\nEscoliosis lumbar de convexidad izquierda. Tejidos blandos de la pared del abdomen y la pelvis de aspecto normal.   \r\n \r\nCONCLUSIÓN\r\nEstudio negativo para litiasis del tracto urinario.\r\nEscoliosis lumbar de convexidad izquierda.\r\n','2024-04-21 15:17:03',NULL,1,1,'2024-05-16 22:44:44','2024-05-16 22:44:44'),(55,46,65,NULL,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE',NULL,NULL,NULL,NULL,1,0,'2024-05-16 22:44:44','2024-05-16 22:44:44'),(56,47,65,NULL,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE',NULL,NULL,NULL,NULL,1,0,'2024-05-16 22:44:45','2024-05-16 22:44:45'),(57,48,65,10,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-21 16:31:50','Atenció: 5956531\r\nFecha y Hora: 2024-04-21 16:29:47\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\n\r\nEstudio escanográfico realizado con adquisición helicoidal axial desde la base del craneo y hasta el vértex.\r\n\r\nHALLAZGOS\r\nHipodensidad de la sustancia blanca periventricular, hallazgo secundarios cambios por leucoencefalopatía.\r\nLesión hipodensa corticosubcortical en el hemisferio cerebeloso derecho por lesión isquémica antigua\r\nEl resto del parénquima nervioso visualizado de ambos hemisferios cerebrales es de apariencia normal. No hay signos de calcificación ohemorragia.\r\nLas estructuras parenquimatosas de la fosa posterior tienen apariencia habitual.\r\nEl sistema ventricular es de tamaño y forma normal, localizado en posición central.\r\nLas cisternas basales y la amplitud del espacio subaracnoideo son de características usuales. Se descartan colecciones extra axiales compresivas.\r\nLas diferentes cavidades neumatizadas de la base del cráneo no presentan alteración.\r\n\r\nCONCLUSIÓN\r\nCAMBIOS POR LEUCOENCEFALOPATÍA MICROANGIOPÁTICA, HIPERTENSIVA Y/O ATEROSCLERÓTICA.\r\nLESION ISQUÉMICA ANTIGUA EN EL HEMISFERIO CEREBELOSO DERECHO\r\n','2024-04-21 16:32:53',NULL,1,1,'2024-05-16 22:44:45','2024-05-16 22:44:45'),(58,49,80,NULL,'879420','TOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL',NULL,NULL,NULL,NULL,1,0,'2024-05-16 22:44:45','2024-05-16 22:44:45'),(59,50,80,10,'879420','TOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL','2024-04-21 17:39:54','Atenció: 5955001\r\nFecha y Hora: 2024-04-21 17:38:30\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE ABDOMEN Y  PELVIS ABDOMEN TOTAL\r\n\r\nTÉCNICA\r\n\r\nCon técnica helicoidal se realiza TAC de la totalidad del abdomen tal como se indica en la radiografía digital se administra medio decontraste I.V yodado no iónico hidrosoluble en bolo y medio de contraste V.O.\r\n\r\nHALLAZGOS\r\nEl hígado se observa de tamaño, forma, contornos y densidad normales, no hay lesiones focalizadas.\r\nNo hay dilatación de la via biliar intra ni extrahepatica. La vesicula está ausente con presencia de clips quirúrgicos\r\nEl páncreas, el bazo, los riñones y las suprarenales son normales.\r\nNo hay dilatación de los sistemas colectores renales. La vejiga es normal.\r\nútero en aVF, no se identifican masas anexiales\r\nAorta, vena cava inferior y demás estructuras vasculares observadas son de curso calibre normal.\r\nNo hay masas ni adenomegalias\r\nEstomago y asas intestinales delgadas y gruesas son de apariencia escanografica usual. apéndice cecal de aspecto normal\r\nNo hay masas ni líquido libre en cavidad peritoneal ni en cavidad pélvica.\r\nEstructuras oseas y demas tejidos blandos observados son normales.\r\n\r\nCONCLUSIÓN\r\nTAC DE ABDOMEN TOTAL NORMAL','2024-04-21 17:40:49',NULL,1,1,'2024-05-16 22:44:45','2024-05-16 22:44:45'),(60,51,77,10,'879301','TOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE','2024-04-21 21:11:32','Atenció: 5947583\r\nFecha y Hora: 2024-04-21 21:09:09\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE\r\n\r\n\r\nTÉCNICA\r\nCon técnica helicoidal se realiza TAC simple de la totalidad del tórax, tal como lo indica la radiografía digital.\r\n\r\nHALLAZGOS\r\nLas estructuras vasculares mediastinales son de curso y calibre normales.\r\nCorazón de apariencia escanográfica usual.\r\nCalcificaciones ateromatosas de la aorta\r\nSonda gástrica\r\nTraquea y bronquios fuentes normales.\r\nAtelectasias planas basales posteriores bilaterales\r\nEspacios pleurales libres\r\nCambios degenerativos en la columna torácica\r\n\r\nCONCLUSIÓN\r\nATELECTASIAS PLANAS BASALES POSTERIORES BILATERALES\r\nNO HAY CONSOLIDACIONES QUE SUGIERAN BRONCOASPIRACIÓN\r\nCAMBIOS DEGENERATIVOS EN LA COLUMNA TORÁCICA','2024-04-21 21:12:11',NULL,1,1,'2024-05-16 22:44:45','2024-05-16 22:44:45'),(61,52,65,10,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-21 23:18:19','Atenció: 5956974\r\nFecha y Hora: 2024-04-21 23:17:24\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nSe valora tomografia de craneo simple adquisicion axial desde la base del craneo a la convexidad, con reconstrucciones coronal y sagital, identificando lo siguiente:\r\n\r\nHALLAZGOS\r\nSe observa hematoma subgaleal parietal izquierdo con un espesor de hasta 12 mm\r\nTejido óseo sin evidencia de lesiones líticas, blásticas ni trazos de fractura.\r\nEn lo valorable de los senos paranasales y celdillas mastoideas con adecuada neumatización.\r\nSeptum nasal central. Órbitas y su contenido de densidad normal.\r\nLínea interhemisférica central.\r\nHemisferios cerebrales simétricos, con adecuada profundidad de los surcos y cisuras, las circunvoluciones son de espesor normal, con adecuada diferenciación entre la sustancia gris y blanca.\r\nLos ganglios de la base, el cuerpo calloso y el mesencéfalo son de forma y densidad normal.\r\nGlándula hipófisis de forma, tamaño y densidad normal.\r\nHemisferios cerebelosos simétricos, de tamaño y densidad normal.\r\nEl sistema ventricular, el espacio subaracnoideo y las cisternas son de aspecto normal.\r\n\r\nCONCLUSIÓN\r\nHematoma subgaleal parietal izquierdo.\r\n','2024-04-21 23:18:36',NULL,1,1,'2024-05-16 22:44:45','2024-05-16 22:44:45'),(62,53,65,10,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-21 23:43:05','Atenció: 5956964\r\nFecha y Hora: 2024-04-21 23:42:07\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nSe valora tomografia de craneo simple adquisicion axial desde la base del craneo a la convexidad, con reconstrucciones coronal y sagital, identificando lo siguiente:\r\n\r\nHALLAZGOS\r\nPiel y tejidos blandos de densidad normal.\r\nTejido óseo sin evidencia de lesiones líticas, blásticas ni trazos de fractura.\r\nEn lo valorable de los senos paranasales y celdillas mastoideas con adecuada neumatización.\r\nÓrbitas y su contenido de densidad normal.\r\nSe observa imagen cóncava fronto-parietooccipito-temporal izquierdo con un espesor de 27 mm de densidad heterogénea hiper atenuante, con áreas irregulares de mayor densidad hacia la región occipital, la cual condiciona efecto de volumen obliterando los surcos y cisuras, el ventriculo lateral ipsialteral, desplazando la línea media en 11 mm, los hemisferios cerebrales conservan la diferenciación entre la sustancia gris y blanca, sin embargo se identifica disminución en la densidad de la sustancia blanca del hemisferio cerebral izquierdo.\r\nSe observan calcificaciones ganglios basales simétricas, el cuerpo calloso y el mesencéfalo son de forma y densidad normal.\r\nGlándula hipófisis de forma, tamaño y densidad normal.\r\nHemisferios cerebelosos simétricos, de tamaño y densidad normal.\r\nLas cisternas son de aspecto normal.\r\nSe observa calcificación fisiológica de los plexos coroides, la glándula pineal.\r\nSe observa calcificación en la pared de las carótidas internas porción cavernosa.\r\n\r\nCONCLUSIÓN\r\nHematoma subdural fronto-parieto-occipito-temporal izquierdo asociado a hernia subfalcina y edema cerebral.\r\nEnfermedad vascular arterioesclerótica.\r\nNOTA: Estudio con hallazgos críticos que requiere evaluación inmediata por el médico tratante','2024-04-21 23:43:25',NULL,1,1,'2024-05-16 22:44:46','2024-05-16 22:44:46'),(63,54,65,10,'879111','TOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE','2024-04-21 23:45:32','Atenció: 5956968\r\nFecha y Hora: 2024-04-21 23:44:15\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE CRANEO SIMPLE\r\n\r\nTÉCNICA\r\nSe valora tomografia de craneo simple adquisicion axial desde la base del craneo a la convexidad, con reconstrucciones coronal y sagital, identificando lo siguiente:\r\n\r\nHALLAZGOS\r\nSe observa aumento del espesor y densidad de los tejidos blandos epicraneales de la región parietal derecha.\r\nTejido óseo sin evidencia de lesiones líticas, blásticas ni trazos de fractura.\r\nEn lo valorable de los senos paranasales y celdillas mastoideas con adecuada neumatización.\r\nSeptum nasal central. Órbitas y su contenido de densidad normal.\r\nA nivel fronto parieto temporal izquierdo se observa imagen cóncava laminar hiperdensa con un espesor máximo de 5 mm.\r\nSe observa ocupación lineal hiperatenuante de los surcos y cisuras fronto parietotemporal izquierdos.\r\nEl tentorio cerebral izquierdo se observa engrosado y con aumento en la densidad.\r\nEl parénquima cerebral conserva la diferenciación entre la sustancia gris y blanca, se observa leve desplazamiento de la línea media hacia la derecha en 5 mm.\r\nSe observan pequeñas calcificaciones simétricas ganglio basales bilaterales, el cuerpo calloso y el mesencéfalo son de forma y densidad normal.\r\nGlándula hipófisis de forma, tamaño y densidad normal.\r\nHemisferios cerebelosos simétricos, de tamaño y densidad normal.\r\nEl sistema ventricular y las cisternas son de aspecto normal.\r\nSe observa calcificación fisiológica de los plexos coroides, la glándula pineal.\r\n\r\nCONCLUSIÓN\r\nHematoma laminar subdural frontoparietotemporal izquierdo qué condiciona efecto de volumen desplazando la línea media.\r\nHemorragia subaracnoidea frontoparietotemporal izquierda.\r\nHematoma subdural laminar del tentorio del cerebelo izquierdo.\r\nEdema en los tejidos blandos epicraneales en la región parietal derecha.\r\nCalcificaciones simétricas ganglios basales, se sugiere correlacionar clínicamente descartar etiología metabólica.','2024-04-21 23:45:51',NULL,1,1,'2024-05-16 22:44:46','2024-05-16 22:44:46'),(64,55,104,4,'883522','RESONANCIA NUCLEAR MAGNETICA DE ARTICULACIONES DE MIEMBRO INFERIOR PELVIS   RODILLA  PIE Y O CUELLO DE PIE','2024-04-22 07:40:35','Atenció: 5956358\r\nFecha y Hora: 2024-04-22 07:37:44\r\n\r\nRESONANCIA NUCLEAR MAGNETICA DE RODILLA DERECHA\r\nTÉCNICA\r\nEn equipo superconductor de 1.5T se adquiere estudio multiplanar y se obtienen múltiples secuencias centradas en la rodilla.\r\n\r\nHALLAZGOS\r\nESTRUCTURAS ÓSEAS / CARTILAGO ARTICULAR\r\nLa señal de la médula ósea es normal. No se identifican fracturas ni otras lesiones óseas.\r\n- Compartimento patelofemoral: Alteración en la intensidad de señal en T2 y laceraciones en el espesor con compromiso de mas del 50% del espesor.\r\n- Compartimento femorotibial medial: cartílago articular de espesor y señal normal.\r\n- Compartimento femorotibial lateral: cartílago articular de espesor y señal normal.\r\nMENISCOS\r\n- Menisco lateral: Desgarro complejo con componente horizontal del cuerno anterior radial del cuerpo.\r\n- Menisco medial: Desgarro complejo con componente radial del cuerpo y oblicuo del cuerno posterior.\r\nLIGAMENTOS CRUZADOS\r\nDesgarro completo del LCA.\r\nESTRUCTURAS DE SOPORTE MEDIAL\r\nLigamento colateral interno integro sin lesiones o rupturas.\r\nNo hay lesiones evidentes en los ligamentos meniscocapsulares profundos.\r\nNo se identifican lesiones en el ligamento posterior oblicuo.\r\nEl tendón del semimembranoso y los diferentes componentes de la pata de ganso muestran morfología normal\r\nESTRUCTURAS DE SOPORTE LATERAL\r\nLigamento colateral lateral se encuentra integro.\r\nLa inserción tendinosa del bíceps femoral y el tendón conjunto son de características normales.\r\nTendón poplíteo de apariencia normal.\r\nNo hay lesiones en la banda ileotibial.\r\nLas demás estructuras de la esquina posterolateral se encuentran integras, sin lesiones o rupturas.\r\nMECANISMO EXTENSOR\r\nEl tendón del cuádriceps y patelar son morfología y señal normales.\r\nRetináculos patelofemorales de características normales.\r\nLÍQUIDO ARTICULAR Y GRASA DE HOFFA\r\nNo hay aumento del líquido articular. Quiste de Baker de 27x20 mm. No se observan cuerpos libres interarticulares.\r\nGrasa de Hoffa de características normales\r\nOTROS HALLAZGOS\r\nNo se identifican masas en tejidos blandos.\r\n\r\nCONCLUSIÓN\r\nDesgarro completo del LCA.\r\nDesgarros meniscales.\r\nCambios de condromalacia patelar grado III.\r\nQuiste de Baker.','2024-04-22 07:42:46',NULL,1,1,'2024-05-16 22:44:46','2024-05-16 22:44:46'),(65,56,125,4,'','RESONANCIA MAGNETICA DE OIDOS','2024-04-22 07:41:14','Atenció: 5954205\r\nFecha y Hora: 2024-04-22 07:38:26\r\n\r\nRESONANCIA MAGNETICA DE OIDOS\r\n\r\nTÉCNICA\r\nUnidad superconductora que opera a 1.5 T. Se realizaron secuencias T1 y T2 , en cortes axiales y coronales finos, con énfasis sobre la\r\nregión de los ángulos pontocerebelosos y el hueso temporal (oídos), antes y después de la administración endovenosa de medio de\r\ncontraste paramagnético (gadolinio).\r\n\r\nHALLAZGOS\r\nNo se evidencian alteraciones en la intensidad de señal o el volumen del parénquima de la fosa posterior. En especial no hay lesiones\r\nfocales del tallo cerebral y se identifican sin alteración el curso y morfología del complejo de pares craneales VII-VIII. No se registran\r\nfocos de hipercaptación anormal con la administración del medio de contraste.\r\nLas cisternas peritroncales y en especial las del los ángulos ponto cerebelosos se encuentran libres.\r\nHay adecuado vacío de señal de las estructuras vasculares arteriales del sistema vertebro basilar.\r\nNo se observan alteraciones de las porciones visualizadas de las regiones mastoideas ni de las estructuras del laberinto membranoso en el hueso temporal.\r\n\r\nCONCLUSIÓN\r\nRESONANCIA MAGNETICA DE OIDOS SIMPLE Y CON CONTRASTE DENTRO DE LIMITES NORMALES.','2024-04-22 07:42:29',NULL,1,1,'2024-05-16 22:44:46','2024-05-16 22:44:46'),(66,57,83,4,'879520','TOMOGRAFIA AXIAL COMPUTADA DE MIEMBROS INFERIORES Y ARTICULACIONES','2024-04-22 10:04:27','Atenció: 5957031\r\nFecha y Hora: 2024-04-22 09:35:39\r\n\r\nTAC DE ANTEBRAZO IZQUIERDO:\r\n\r\nSe realizaron cortes axiales tomográficos computarizados cada 3 mm sobre el antebrazo obteniendo imágenes con algoritmo de reconstrucción para estructuras óseas y tejido blando.\r\nFractura oblicua completa del tercio distal del cúbito que compromete la diáfisis con desplazamiento de fragmentos principales en sentido palmar.\r\nFractura oblicua completa del tercio distal del radio en localización diafisiaria con desplazamiento de fragmentos principales en sentido dorsal-medial.\r\nIncremento en el coeficiente de atenuación de la grasa del tejido celular cutáneo del tercio distal del antebrazo con presencia imágenes aéreas libres a este mismo nivel por edema/enfisema.\r\nNo se observan otras alteraciones en las estructuras óseas.\r\nHay pérdida de la relaciones articulares cúbito-carpianas por luxación.\r\nLas demás relaciones articulares se encuentran conservadas.\r\n\r\nOpinión: Fracturas del tercio distal del cúbito y el radio asociadas a edema/enfisema de tejidos blandos. Luxación de la articulación del puño.','2024-04-22 11:46:15',NULL,1,1,'2024-05-16 22:44:46','2024-05-16 22:44:46'),(67,58,77,4,'879301','TOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE','2024-04-22 09:40:01','Atenció: 5956963\r\nFecha y Hora: 2024-04-22 09:39:17\r\n\r\nTOMOGRAFIA AXIAL COMPUTADA DE TORAX SIMPLE\r\n\r\nTÉCNICA\r\nCon técnica helicoidal se realiza tomografía de la totalidad del tórax tal como se indica en la radiografía digital.\r\n\r\nHALLAZGOS\r\nLa tráquea y los grandes bronquios son de curso y calibre normal, no se observan lesiones murales o intraluminales.\r\nSilueta cardiaca de tamaño normal. Saco pericárdico sin alteraciones.\r\nLos grandes vasos del mediastino son de curso y morfología usual.\r\nEl esófago y las demás estructuras mediastinales son de aspecto tomográfico normal.\r\nNo se visualizan adenomegalias en el presente estudio.\r\nLos hilios pulmonares son de aspecto tomográfico usual.\r\nConsolidación con broncograma aéreo en el lóbulo medio e inferior derecho con patrón en vidrio deslustrado adyacente, patrón de árbol en gemación de distribución aleatoria en ambos campos pulmonares con mayor compromiso en el sector derecho.\r\nNo hay derrame pleural.\r\nLo visualizado de las estructuras óseas y de los tejidos blandos de la pared torácica no muestra alteraciones.\r\nNo se observan alteraciones en el abdomen superior.\r\n\r\nCONCLUSIÓN\r\nNeumonía multilobar.\r\nEnfermedad ateromatosa.','2024-04-22 09:40:25',NULL,1,1,'2024-05-16 22:44:46','2024-05-16 22:44:46'),(68,59,98,4,'883401','RESONANCIA NUCLEAR MAGNETICA DE ABDOMEN','2024-04-22 20:23:42','Atenció: 5957290\r\nFecha y Hora: 2024-04-22 11:09:08\r\n\r\nRESONANCIA MAGNÉTICA DE ABDOMEN CON CONTRASTE:\r\n\r\nTécnica:\r\nSe practican secuencias con técnica dual eco, difusión y FSE teniendo imágenes en los planos axial, sagital y coronal potenciadas en T1 y T2 antes y después de la administración de material de contraste paramagnético endovenoso.\r\nHallazgos:\r\nHígado de forma, tamaño, contornos y situación normales. En el segmento II del parénquima hepático se observa imagen lo gruesa bien definida de aproximadamente 10 x 7 mm de diámetro hipointensa en T1e hiperintensa en T2 sin realce luego de la administración de gadolinio correspondiente a quiste simple.\r\nVesícula biliar distendida paredes delgadas con contenido líquido. No hay dilatación de la vía biliar intra ni extrahepática.\r\nLas glándulas suprarrenales, el páncreas y el bazo en morfología e intensidad de señal normales.\r\nAmbos riñones de forma, tamaño, contornos e intensidad de señal normales. No hay dilatación de los sistemas pielocaliciales.\r\nLa porción valorada la de los músculos psoas tiene morfología e intensidad de señal normales.\r\nEstructuras vasculares de curso y calibre normales; no se identifican adenomegalias retroperitoneales.\r\nNo se observa líquido libre en cavidad abdominal\r\nCambios degenerativos de la columna dorsolumbar. Diástasis de los músculos rectos abdominales en región umbilical con protrusión de grasa mesentérica\r\n\r\nOpinión: Quiste hepático simple. Hernia umbilical.','2024-04-24 07:37:12',NULL,1,1,'2024-05-16 22:44:47','2024-05-16 22:44:47'),(69,60,123,7,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-23 13:59:46','Atenció: 5956688\r\nFecha y Hora: 2024-04-22 12:20:15\r\n\r\n\r\n\r\nRADIOGRAFIA DE TORAX\r\n\r\nProyección única AP.\r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n','2024-04-25 13:38:04',NULL,1,1,'2024-05-16 22:44:47','2024-05-16 22:44:47'),(70,61,123,7,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-23 13:59:15','Atenció: 5956665\r\nFecha y Hora: 2024-04-22 12:20:34\r\n\r\n\r\n\r\nRADIOGRAFIA DE TORAX\r\n\r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nCambios degenerativos de la columna dorsal.\r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE TÓRAX DENTRO DE LÍMITES NORMALES.\r\n','2024-04-25 13:37:53',NULL,1,1,'2024-05-16 22:44:47','2024-05-16 22:44:47'),(71,62,48,7,'873313','RADIOGRAFIA DE PIERNA AP Y LATERAL','2024-04-23 13:58:57','Atenció: 5956649\r\nFecha y Hora: 2024-04-22 12:20:54\r\n\r\n\r\nRADIOGRAFIA DE PIERNA IZQUIERDA\r\n\r\nAumento en el espesor y la densidad de los tejidos blandos proximales de la pierna por edema.\r\nNo se observan alteraciones en las estructuras óseas visualizadas.\r\nLas relaciones articulares se encuentran conservadas. \r\n\r\nCONCLUSIÓN:  EDEMA DE TEJIDOS BLANDOS EN LA PIERNA.\r\n\r\n','2024-04-25 13:37:45',NULL,1,1,'2024-05-16 22:44:47','2024-05-16 22:44:47'),(72,63,123,7,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-23 13:58:39','Atenció: 5956660\r\nFecha y Hora: 2024-04-22 12:21:17\r\n\r\n\r\n\r\nRADIOGRAFIA DE TORAX\r\n\r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n\r\nCONCLUSIÓN: RADIOGRAFÍA DE TÓRAX DENTRO DE LÍMITES NORMALES.\r\n','2024-04-25 13:36:18',NULL,1,1,'2024-05-16 22:44:48','2024-05-16 22:44:48'),(73,64,123,7,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-23 13:57:54','Atenció: 5956552\r\nFecha y Hora: 2024-04-22 12:23:50\r\n\r\n\r\nRADIOGRAFIA DE TORAX\r\n\r\nProyección única AP.\r\nOpacidad lineal no septal parenquimatosa pulmonar basal derecha correspondiente a atelectasia planas.\r\nCorazón aumentado de tamaño.\r\nLa transparencia y vascularización del resto de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n\r\n\r\n','2024-04-25 13:37:25',NULL,1,1,'2024-05-16 22:44:48','2024-05-16 22:44:48'),(74,65,123,7,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-23 13:57:38','Atenció: 5956633\r\nFecha y Hora: 2024-04-22 12:24:25\r\n\r\n\r\n\r\nRADIOGRAFIA DE TORAX\r\n\r\nProyección única AP.\r\nLa transparencia y vascularización de los parénquimas pulmonares son satisfactorias.\r\nNo hay evidencia de lesión pleural.\r\nLa porción valorada de la vía aérea superior tiene configuración y calibre normales.\r\nMediastino e hilios libres.\r\nCorazón de tamaño normal.\r\nNo hay particularidad en las estructuras óseas ni tejidos blandos.\r\n','2024-04-25 13:35:58',NULL,1,1,'2024-05-16 22:44:48','2024-05-16 22:44:48'),(75,66,123,NULL,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-22 14:40:08','REPETIDA',NULL,NULL,1,0,'2024-05-16 22:44:48','2024-05-16 22:44:48'),(76,67,123,NULL,'','RADIOGRAFIA DE TORAX  PA O   AP Y  LATERAL DE CUBITO LATERAL  OBLICUAS O LATERAL','2024-04-22 14:40:42','REPETIDA',NULL,NULL,1,0,'2024-05-16 22:44:48','2024-05-16 22:44:48'),(77,68,123,NULL,'','RADIOGRAFIA 